import React, { useState, useEffect } from 'react';
import './App.css';

const BTC_FEED_ID = '0xe62df6c8b4a85fe1a67db44dc12de5db330f7ac66b72dc658afedf0f4a415b43';
const HERMES_API = 'https://hermes.pyth.network/v2/updates/price/latest';

interface PriceData {
  price: number;
  timestamp: number;
}

type GameState = 'waiting' | 'countdown' | 'locked' | 'result';
type Prediction = 'up' | 'down' | null;

function App() {
  const [currentPrice, setCurrentPrice] = useState<PriceData | null>(null);
  const [startPrice, setStartPrice] = useState<PriceData | null>(null);
  const [gameState, setGameState] = useState<GameState>('waiting');
  const [prediction, setPrediction] = useState<Prediction>(null);
  const [countdown, setCountdown] = useState(60);
  const [wins, setWins] = useState(0);
  const [losses, setLosses] = useState(0);
  const [resultMessage, setResultMessage] = useState('');

  // Fetch latest BTC price
  const fetchPrice = async (): Promise<PriceData | null> => {
    try {
      const response = await fetch(`${HERMES_API}?ids[]=${BTC_FEED_ID}`);
      const data = await response.json();

      if (data.parsed && data.parsed[0]) {
        const priceData = data.parsed[0].price;
        const price = parseInt(priceData.price) * Math.pow(10, priceData.expo);
        return {
          price: price,
          timestamp: Date.now()
        };
      }
      return null;
    } catch (error) {
      console.error('Failed to fetch price:', error);
      return null;
    }
  };

  // Update current price every 2 seconds
  useEffect(() => {
    const updatePrice = async () => {
      const price = await fetchPrice();
      if (price) setCurrentPrice(price);
    };

    updatePrice(); // Initial fetch
    const interval = setInterval(updatePrice, 2000);
    return () => clearInterval(interval);
  }, []);

  // Countdown timer
  useEffect(() => {
    if (gameState === 'countdown') {
      if (countdown > 0) {
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
      } else {
        // Time's up! Show result
        showResult();
      }
    }
  }, [gameState, countdown]);

  const makePrediction = async (pred: Prediction) => {
    if (!currentPrice || gameState !== 'waiting') return;

    setPrediction(pred);
    setStartPrice(currentPrice);
    setGameState('countdown');
    setCountdown(60);
  };

  const showResult = () => {
    if (!startPrice || !currentPrice || !prediction) return;

    const priceChange = currentPrice.price - startPrice.price;
    const wasCorrect = (prediction === 'up' && priceChange > 0) || 
                      (prediction === 'down' && priceChange < 0);

    if (wasCorrect) {
      setWins(wins + 1);
      setResultMessage(`✅ Correct! BTC moved ${priceChange > 0 ? 'UP' : 'DOWN'} by $${Math.abs(priceChange).toFixed(2)}`);
    } else {
      setLosses(losses + 1);
      setResultMessage(`❌ Wrong! BTC moved ${priceChange > 0 ? 'UP' : 'DOWN'} by $${Math.abs(priceChange).toFixed(2)}`);
    }

    setGameState('result');
  };

  const resetGame = () => {
    setGameState('waiting');
    setPrediction(null);
    setStartPrice(null);
    setCountdown(60);
    setResultMessage('');
  };

  const accuracy = wins + losses > 0 ? Math.round((wins / (wins + losses)) * 100) : 0;

  return (
    <div className="app">
      <header>
        <h1>🚀 BTC Price Predictor</h1>
        <p>Will Bitcoin go UP or DOWN in the next minute?</p>
      </header>

      <div className="price-display">
        <h2>Current BTC Price</h2>
        <div className="price">
          ${currentPrice?.price.toFixed(2) || 'Loading...'}
        </div>
      </div>

      <div className="game-area">
        {gameState === 'waiting' && (
          <div className="prediction-buttons">
            <button 
              className="predict-btn up" 
              onClick={() => makePrediction('up')}
              disabled={!currentPrice}
            >
              📈 Predict UP
            </button>
            <button 
              className="predict-btn down" 
              onClick={() => makePrediction('down')}
              disabled={!currentPrice}
            >
              📉 Predict DOWN
            </button>
          </div>
        )}

        {gameState === 'countdown' && (
          <div className="countdown">
            <h3>Your prediction: {prediction === 'up' ? '📈 UP' : '📉 DOWN'}</h3>
            <div className="timer">{countdown}s</div>
            <p>Starting price: ${startPrice?.price.toFixed(2)}</p>
            <p>Current price: ${currentPrice?.price.toFixed(2)}</p>
          </div>
        )}

        {gameState === 'result' && (
          <div className="result">
            <h3>{resultMessage}</h3>
            <div className="price-comparison">
              <p>Started at: ${startPrice?.price.toFixed(2)}</p>
              <p>Ended at: ${currentPrice?.price.toFixed(2)}</p>
            </div>
            <button className="play-again" onClick={resetGame}>
              Play Again
            </button>
          </div>
        )}
      </div>

      <div className="stats">
        <h3>Your Score</h3>
        <div className="score-grid">
          <div className="stat">
            <span className="stat-label">Wins</span>
            <span className="stat-value">{wins}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Losses</span>
            <span className="stat-value">{losses}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Accuracy</span>
            <span className="stat-value">{accuracy}%</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.app {
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 30px;
}

header {
  text-align: center;
}

header h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

header p {
  font-size: 1.2rem;
  opacity: 0.9;
}

.price-display {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 30px;
  text-align: center;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.price-display h2 {
  font-size: 1.3rem;
  margin-bottom: 15px;
  opacity: 0.9;
}

.price {
  font-size: 3rem;
  font-weight: bold;
  color: #f39c12;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.game-area {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 30px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  text-align: center;
}

.prediction-buttons {
  display: flex;
  gap: 20px;
  justify-content: center;
  flex-wrap: wrap;
}

.predict-btn {
  padding: 20px 40px;
  font-size: 1.3rem;
  font-weight: bold;
  border: none;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.3s ease;
  min-width: 200px;
  text-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

.predict-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(0,0,0,0.3);
}

.predict-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.predict-btn.up {
  background: linear-gradient(135deg, #27ae60, #2ecc71);
  color: white;
}

.predict-btn.down {
  background: linear-gradient(135deg, #e74c3c, #c0392b);
  color: white;
}

.countdown {
  text-align: center;
}

.countdown h3 {
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.timer {
  font-size: 4rem;
  font-weight: bold;
  color: #f39c12;
  margin: 20px 0;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.countdown p {
  font-size: 1.1rem;
  margin: 10px 0;
  opacity: 0.9;
}

.result {
  text-align: center;
}

.result h3 {
  font-size: 1.8rem;
  margin-bottom: 20px;
}

.price-comparison {
  background: rgba(0,0,0,0.2);
  border-radius: 10px;
  padding: 20px;
  margin: 20px 0;
}

.price-comparison p {
  font-size: 1.1rem;
  margin: 8px 0;
}

.play-again {
  padding: 15px 30px;
  font-size: 1.2rem;
  font-weight: bold;
  background: linear-gradient(135deg, #3498db, #2980b9);
  color: white;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 20px;
}

.play-again:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 15px rgba(0,0,0,0.3);
}

.stats {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 25px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.stats h3 {
  text-align: center;
  margin-bottom: 20px;
  font-size: 1.4rem;
}

.score-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.stat {
  text-align: center;
  background: rgba(0,0,0,0.2);
  border-radius: 10px;
  padding: 15px;
}

.stat-label {
  display: block;
  font-size: 0.9rem;
  opacity: 0.8;
  margin-bottom: 5px;
}

.stat-value {
  display: block;
  font-size: 2rem;
  font-weight: bold;
  color: #f39c12;
}

@media (max-width: 600px) {
  .app {
    padding: 15px;
    gap: 20px;
  }

  header h1 {
    font-size: 2rem;
  }

  .price {
    font-size: 2.5rem;
  }

  .prediction-buttons {
    flex-direction: column;
    align-items: center;
  }

  .predict-btn {
    min-width: 250px;
  }

  .score-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }
}

/* Reset and base styles */
* {
  box-sizing: border-box;
}

html, body, #root {
  margin: 0;
  padding: 0;
  min-height: 100vh;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  min-height: 100vh;
}
